void Solver::bump_var(int var, double coeff) {
    // compute increment and update activity
    double inc = var_inc * coeff;
    double newAct = activity[var] + inc;
    activity[var] = newAct;

    // global rescaling only when values become too large
    const double LIMIT = 1e150;
    if (var_inc > LIMIT || newAct > LIMIT) {
        const double SCALE = 1e-150;
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    // keep VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
